/**
 * Re-runs the ADMISSION decision for one saved row and persists the
 * result: do its declared references still expand, do its hidden secrets
 * still redeem, and does policy still admit the project to own it.
 *
 * NOTHING CONTACTS A PROVIDER. The live provider round trip is
 * POST /configurations/check_stored_connection/{project_id}/{config_id},
 * and that route stores nothing. The two are separate on purpose: a
 * provider outage must not withdraw every credential in a project from the
 * gateway, and a credential whose vault secret has been deleted must not
 * stay usable because the provider still answers.
 *
 * It writes `status_ok` and NO field of the row — no data, no meta, no
 * updated_at. An unmanaged row (a generic configuration, or an imported
 * model with no ai_credentials) keeps the status its writer stored.
 * @summary Re-derive a stored configuration's status_ok
 */
export const revalidateConfiguration = async (
  projectId: string,
  configId: string,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<revalidateConfigurationResponse> => {
  return eliteaFetch<revalidateConfigurationResponse>(
    getRevalidateConfigurationUrl(projectId, configId),
    {
      ...options,
      method: "POST",
    },
  );
};

